mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("n=4 edges=(0,1),(1,2),(2,3),(3,0)","true"),
        ("n=3 edges=(0,1),(1,2),(2,0)","false"),
        ("n=5 edges=(0,1),(2,3)","true"),
        ("n=1 edges=","true"),
        ("n=4 edges=(0,1),(0,2),(0,3)","true"),
        ("  \nn=4 edges=(0,1),(1,2),(2,3),(3,0)\n  ","true"),
        ("\nn=4 edges=(0,1),(0,2),(0,3)\n","true")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS bipartite-coloring");
}
